-- Generado por scripts/gen-territory-seed.test.ts desde src/data. Todo entra como BORRADOR: nada se publica solo.
-- INSERT OR IGNORE: si una provincia ya se creó en el panel, se respeta tal cual.
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('azua', 'azua', 'Azua', 'sur', 'Azua de Compostela', 'draft', 'Ciudad histórica con la Batalla del 19 de Marzo y paisajes sureños.', 'Azua de Compostela es una de las ciudades más antiguas del continente americano, fundada en 1504. Fue escenario de la histórica Batalla del 19 de Marzo de 1844, primera batalla de la independencia dominicana. La provincia ofrece paisajes variados desde montañas hasta costas semiáridas.', 'https://images.unsplash.com/photo-1532483235718-2262d9c757cd?w=1200&h=800&fit=crop&q=80', 18.4531, -70.7289, 'Noviembre a Abril', 'Clima seco y cálido, una de las zonas más calurosas del país.', '2 horas desde Santo Domingo por la autopista del sur.', '["Batalla del 19 de Marzo","Ciudad colonial","Playas sureñas","Montañas"]', '["Chenchén","Chivo guisado","Habas guisadas"]', '["cultura","ecoturismo"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('bahoruco', 'bahoruco', 'Bahoruco', 'sur', 'Neiba', 'draft', 'Sierra de Bahoruco con la mayor diversidad de orquídeas del Caribe.', 'La provincia Bahoruco es un paraíso para los amantes de la naturaleza. La Sierra de Bahoruco alberga más de 180 especies de orquídeas, 52 de ellas endémicas, y 49 especies de aves endémicas. Es uno de los sitios de mayor biodiversidad del Caribe y un destino emergente para el ecoturismo científico.', 'https://images.unsplash.com/photo-1780926539672-71385c3452a4?w=1200&h=800&fit=crop&q=80', 18.4833, -71.4167, 'Enero a Abril para orquídeas en flor', 'Clima variado por altitud, desde cálido en valles hasta frío en cumbres.', '4 horas desde Santo Domingo.', '["Sierra de Bahoruco","180+ orquídeas","Aves endémicas","Bosque nublado"]', '["Chivo guisado","Habichuelas con dulce","Dulce de batata"]', '["ecoturismo","montaña"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('barahona', 'barahona', 'Barahona', 'sur', 'Santa Cruz de Barahona', 'draft', 'Donde la montaña se encuentra con el mar en paisajes dramáticos.', 'Barahona ofrece algunos de los paisajes más dramáticos del Caribe, donde las montañas de la Sierra de Bahoruco descienden directamente al mar. Es famosa por sus minas de larimar, la piedra azul única de República Dominicana, y sus playas de aguas turquesas.', 'https://images.unsplash.com/photo-1524445361389-3d2c21109015?w=1200&h=800&fit=crop&q=80', 18.2085, -71.1004, 'Noviembre a Abril', 'Clima variado, desde tropical en la costa hasta fresco en las montañas.', '3.5 horas desde Santo Domingo por autopista del sur.', '["Minas de Larimar","Playa San Rafael","Polo Magnético","Cachote"]', '["Chivo guisado","Pescado con coco","Dulce de batata"]', '["ecoturismo","playa","montaña"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('dajabon', 'dajabon', 'Dajabón', 'norte', 'Dajabón', 'draft', 'Frontera norte con Haití y el famoso mercado fronterizo del río Masacre.', 'Dajabón es la principal ciudad fronteriza del norte, separada de Haití por el histórico río Masacre. Su mercado fronterizo es uno de los más activos del Caribe, donde comerciantes de ambos países intercambian productos en un ambiente vibrante y colorido. La provincia ofrece una experiencia cultural fronteriza única.', 'https://images.unsplash.com/photo-1771980590225-26af59a07802?w=1200&h=800&fit=crop&q=80', 19.5489, -71.7083, 'Lunes y viernes (días de mercado)', 'Clima cálido y seco.', '5 horas desde Santo Domingo.', '["Mercado fronterizo","Río Masacre","Cultura fronteriza","Comercio binacional"]', '["Chivo liniero","Plátano maduro","Habichuelas con dulce"]', '["cultura"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories, itinerary, airport, transport) VALUES ('distrito-nacional', 'distrito-nacional', 'Distrito Nacional', 'santo-domingo', 'Santo Domingo de Guzmán', 'draft', 'Corazón político y cultural del país, sede de la Zona Colonial Patrimonio UNESCO.', 'El Distrito Nacional es el centro político, cultural y económico de República Dominicana. Aquí se encuentra la Zona Colonial declarada Patrimonio de la Humanidad, el Malecón de Santo Domingo, los principales museos, teatros y centros comerciales del país. Es la provincia más cosmopolita y vibrante de la nación.', 'https://images.unsplash.com/photo-1771980590225-26af59a07802?w=1200&h=800&fit=crop&q=80', 18.4861, -69.9312, 'Todo el año', 'Clima tropical cálido, 26-32°C promedio.', 'Aeropuerto Las Américas (SDQ) a 25 minutos.', '["Zona Colonial UNESCO","Malecón","Plaza de la Cultura","Gastronomía metropolitana"]', '["La Bandera","Sancocho","Chimichurri","Yaroa"]', '["cultura","ciudad"]', '[{"dia":1,"titulo":"HISTORIA VIVA","lugar":"Zona Colonial","desc":"Recorre las calles más antiguas de América y visita la Catedral Primada."},{"dia":2,"titulo":"SABORES LOCALES","lugar":"Tour Gastronómico","desc":"Prueba la mejor comida dominicana en mercados y restaurantes locales."},{"dia":3,"titulo":"CULTURA & BAILE","lugar":"Clase de Merengue & Vida Nocturna","desc":"Aprende a bailar merengue y disfruta de la noche capitalina."}]', '{"nombre":"Aeropuerto Internacional Las Américas","codigo":"SDQ","distancia":"30 min"}', '[{"tipo":"avion","desde":"Miami","duracion":"2.5 horas","descripcion":"Vuelos directos desde principales ciudades de USA y Europa"},{"tipo":"carro","desde":"Punta Cana","duracion":"2 horas","descripcion":"Por la autopista del Este"},{"tipo":"bus","desde":"Puerto Plata","duracion":"4 horas","descripcion":"Caribe Tours y Metro","precio":"$12"}]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('duarte', 'duarte', 'Duarte', 'norte', 'San Francisco de Macorís', 'draft', 'Tierra del cacao dominicano y los Gigantes del Cibao.', 'La provincia Duarte, con capital en San Francisco de Macorís, es el corazón cacaotero de República Dominicana. Produce el cacao más fino del mundo, reconocido internacionalmente. Además, es hogar de los Gigantes del Cibao en el béisbol profesional y ofrece paisajes naturales con ríos y montañas del nordeste.', 'https://images.unsplash.com/photo-1777380535163-182463e53e0b?w=1200&h=800&fit=crop&q=80', 19.3008, -70.2527, 'Noviembre a Abril', 'Clima tropical húmedo, ideal para el cultivo de cacao.', '2 horas desde Santo Domingo por autopista Duarte.', '["Capital del Cacao","Fincas cacaoteras","Río Jaya","Béisbol profesional"]', '["Chocolate artesanal","Chacá","Habichuelas con dulce","Mofongo"]', '["cultura","aventura"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('el-seibo', 'el-seibo', 'El Seibo', 'este', 'Santa Cruz de El Seibo', 'draft', 'Tierra del turismo ecológico con Montaña Redonda y playas de Miches.', 'El Seibo alberga algunos de los destinos emergentes más emocionantes de República Dominicana. Miches y su costa virgen están siendo desarrollados como el nuevo polo turístico del este. La icónica Montaña Redonda ofrece vistas de 360° y el columpio más famoso del Caribe.', 'https://images.unsplash.com/photo-1681738623292-3a755d6c8611?w=1200&h=800&fit=crop&q=80', 18.7647, -69.0389, 'Diciembre a Abril', 'Clima tropical con brisas costeras refrescantes.', '2 horas desde Santo Domingo.', '["Montaña Redonda","Miches","Playa Esmeralda","Laguna Redonda"]', '["Pescado con coco","Cangrejo guisado","Casabe"]', '["ecoturismo","aventura","playa"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('elias-pina', 'elias-pina', 'Elías Piña', 'sur', 'Comendador', 'draft', 'Frontera con Haití, mercado binacional y tradiciones vudú sincréticas.', 'Elías Piña, en la frontera con Haití, es famosa por su colorido mercado binacional cada lunes y viernes. La provincia ofrece una experiencia cultural única con la fusión de tradiciones dominicanas y haitianas, incluyendo las fiestas de San Santiago con ceremonias sincréticas. Las montañas fronterizas ofrecen paisajes poco explorados.', 'https://images.unsplash.com/photo-1532483235718-2262d9c757cd?w=1200&h=800&fit=crop&q=80', 18.8761, -71.6983, 'Julio para fiestas de Santiago', 'Clima seco y caluroso en los valles.', '4 horas desde Santo Domingo.', '["Mercado binacional","Fiestas de San Santiago","Frontera cultural","Montañas vírgenes"]', '["Chenchén","Chivo guisado","Plátano maduro"]', '["cultura","ecoturismo"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('espaillat', 'espaillat', 'Espaillat', 'norte', 'Moca', 'draft', 'Cuna del merengue con playas vírgenes y tradición cigarrera.', 'Espaillat, con capital en Moca, es conocida como la cuna del merengue típico y tierra de valientes patriotas. La ciudad de Moca es famosa por sus cigarros artesanales y su rica historia política. La provincia también ofrece playas poco exploradas en su costa atlántica.', 'https://images.unsplash.com/photo-1532483235718-2262d9c757cd?w=1200&h=800&fit=crop&q=80', 19.3967, -70.5228, 'Noviembre a Abril', 'Clima tropical con temperaturas agradables en el interior.', '2.5 horas desde Santo Domingo.', '["Merengue típico","Cigarros artesanales","Playas vírgenes","Historia patriótica"]', '["Chenchen","Chivo liniero","Habichuelas con dulce"]', '["cultura","playa"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('hato-mayor', 'hato-mayor', 'Hato Mayor', 'este', 'Hato Mayor del Rey', 'draft', 'Puerta de entrada al Parque Los Haitises y turismo rural auténtico.', 'Hato Mayor es la puerta de entrada al espectacular Parque Nacional Los Haitises desde su vertiente sur. La provincia ofrece turismo rural auténtico con fincas ganaderas, ríos para kayak y un ambiente campestre genuino. Su ubicación estratégica la conecta con los principales destinos del este.', 'https://images.unsplash.com/photo-1715094313256-31859c8ef92e?w=1200&h=800&fit=crop&q=80', 18.7633, -69.2567, 'Noviembre a Mayo', 'Clima tropical húmedo con temporada lluviosa mayo-noviembre.', '1.5 horas desde Santo Domingo.', '["Parque Los Haitises","Turismo rural","Ríos para kayak","Fincas ganaderas"]', '["Carne de res guisada","Moro de habichuelas","Dulce de leche"]', '["ecoturismo","aventura"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('hermanas-mirabal', 'hermanas-mirabal', 'Hermanas Mirabal', 'norte', 'Salcedo', 'draft', 'Tierra de las heroínas Mirabal, símbolo mundial contra la violencia de género.', 'La provincia Hermanas Mirabal (antes Salcedo) rinde homenaje a las hermanas Patria, Minerva y María Teresa Mirabal, heroínas nacionales asesinadas durante la dictadura de Trujillo. El Museo de las Hermanas Mirabal en Conuco es un sitio de peregrinación y reflexión. El 25 de noviembre, Día Internacional de la Eliminación de la Violencia contra la Mujer, se conmemora en su honor.', 'https://images.unsplash.com/photo-1773654757960-360272fa8205?w=1200&h=800&fit=crop&q=80', 19.3783, -70.415, 'Noviembre para conmemoración', 'Clima tropical agradable.', '2.5 horas desde Santo Domingo.', '["Museo Hermanas Mirabal","Casa de las Mirabal","25 de noviembre","Historia de resistencia"]', '["Moro de guandules","Chivo guisado","Habichuelas con dulce"]', '["cultura"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('independencia', 'independencia', 'Independencia', 'sur', 'Jimaní', 'draft', 'Lago Enriquillo, cocodrilos americanos e iguanas en el punto más bajo del Caribe.', 'La provincia Independencia alberga el Lago Enriquillo, el lago más grande y el punto más bajo del Caribe (40 metros bajo el nivel del mar). Es hogar de la mayor población de cocodrilos americanos en estado salvaje, iguanas rinoceronte y flamencos rosados. La Isla Cabritos dentro del lago es un santuario de fauna única.', 'https://images.unsplash.com/photo-1715094313256-31859c8ef92e?w=1200&h=800&fit=crop&q=80', 18.4833, -71.6167, 'Noviembre a Marzo', 'Clima seco y caluroso, una de las zonas más áridas del país.', '4 horas desde Santo Domingo.', '["Lago Enriquillo","Isla Cabritos","Cocodrilos americanos","Iguanas rinoceronte"]', '["Chivo guisado","Pescado de lago","Habichuelas con dulce"]', '["ecoturismo","aventura"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories, about, itinerary, airport, transport) VALUES ('la-altagracia', 'la-altagracia', 'La Altagracia', 'este', 'Salvaleón de Higüey', 'draft', 'La provincia más turística del Caribe, hogar de Punta Cana y Bávaro.', 'La Altagracia es la joya turística de República Dominicana, conocida mundialmente por sus playas de arena blanca y aguas cristalinas. Aquí se encuentran los destinos más exclusivos del Caribe, incluyendo Punta Cana, Bávaro y Cap Cana, con resorts de clase mundial, campos de golf de campeonato y una vibrante vida nocturna.', 'https://images.unsplash.com/photo-1650509570400-90ea78a677b2?w=1200&h=800&fit=crop&q=80', 18.5825, -68.4055, 'Diciembre a Abril', 'Clima tropical con temperaturas promedio de 26-32°C durante todo el año.', 'Aeropuerto Internacional de Punta Cana (PUJ), el más transitado del Caribe.', '["Playas de arena blanca","Resorts todo incluido","Golf de clase mundial","Parques temáticos"]', '["Pescado con coco","Langosta a la criolla","Mofongo de mariscos"]', '["playa","lujo","aventura"]', '{"history":"La Altagracia fue creada como provincia en 1844, al nacer la República Dominicana. Su nombre proviene de la Virgen de la Altagracia, patrona del pueblo dominicano. Higüey, su capital, fue fundada en 1502 por Juan de Esquivel y es hogar de la Basílica Nuestra Señora de la Altagracia, diseñada por los arquitectos franceses André Dunoyer de Segonzac y Pierre Dupré, inaugurada en 1971.","geography":"Ubicada en el extremo oriental de la isla, La Altagracia posee 160 km de costa bañados por el mar Caribe y el océano Atlántico. Su territorio es predominantemente llano con suelos calizos y vegetación subtropical. Incluye las islas Saona y Catalinita, parte del Parque Nacional del Este.","artAndCulture":"La cultura altagraciana gira en torno a las tradiciones religiosas, especialmente la peregrinación anual a la Basílica de Higüey el 21 de enero. Los palos (atabales) y la música de gagá marcan las festividades. La artesanía local incluye trabajos en concha de lambí y madera de coco.","politicalDivision":"La provincia se divide en 4 municipios: Higüey (capital), San Rafael del Yuma, Bávaro y La Otra Banda, además de 7 distritos municipales.","economy":"El turismo es el motor económico principal, con más de 35,000 habitaciones hoteleras que generan el 70% del turismo nacional. La agricultura (caña de azúcar, ganadería) y la pesca complementan la economía local.","demographics":"Población estimada de 390,000 habitantes. Es una de las provincias con mayor crecimiento demográfico debido a la migración laboral vinculada al sector turístico. La mayoría de la población se concentra en Higüey y las zonas turísticas.","location":"Extremo este de la isla de La Española. Limita al norte con el océano Atlántico, al este y sur con el mar Caribe, y al oeste con las provincias El Seibo y La Romana.","pointsOfInterest":[{"name":"Basílica Nuestra Señora de la Altagracia","type":"religioso","description":"Monumento arquitectónico moderno y centro de peregrinación nacional."},{"name":"Parque Nacional del Este","type":"natural","description":"Área protegida con manglares, cuevas taínas y la Isla Saona."},{"name":"Indigenous Eyes Ecological Park","type":"natural","description":"12 lagunas de agua dulce en medio de la selva tropical."},{"name":"Altos de Chavón","type":"cultural","description":"Réplica de villa mediterránea del s. XVI con anfiteatro y galerías."},{"name":"Hoyo Azul","type":"natural","description":"Cenote de aguas turquesas al pie de un acantilado de 75 metros."},{"name":"Museo de Ponce de León","type":"histórico","description":"Casa-fortaleza del conquistador en San Rafael del Yuma."}],"whatToDo":["Buceo y snorkel en Isla Saona y Catalina","Golf en campos de campeonato (Punta Espada, Corales)","Safari en buggies por la campiña","Tirolesa en Scape Park","Peregrinación a la Basílica de Higüey","Paseo en catamarán por la costa","Visita a la Cueva de Padre Nuestro","Observación de manatíes en los manglares"]}', '[{"dia":1,"titulo":"RELAX TOTAL","lugar":"Playa Bávaro & Spa","desc":"Día de playa y tratamientos de spa en tu resort."},{"dia":2,"titulo":"AVENTURA ACUÁTICA","lugar":"Snorkel y Catamarán","desc":"Explora los arrecifes y navega por la costa."},{"dia":3,"titulo":"GOLF & GASTRONOMÍA","lugar":"Campo de Golf & Cena Gourmet","desc":"18 hoyos y cena con vistas al mar."}]', '{"nombre":"Aeropuerto Internacional de Punta Cana","codigo":"PUJ","distancia":"20 min"}', '[{"tipo":"avion","desde":"Santo Domingo","duracion":"45 min","descripcion":"Vuelos directos desde SDQ","precio":"$150"},{"tipo":"carro","desde":"Santo Domingo","duracion":"2 horas","descripcion":"Por la autopista del Este, muy bien señalizada","precio":"$120 (taxi)"},{"tipo":"bus","desde":"Santo Domingo","duracion":"3 horas","descripcion":"Expreso Bávaro con salidas cada hora","precio":"$10"}]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('la-romana', 'la-romana', 'La Romana', 'este', 'La Romana', 'draft', 'Hogar de Casa de Campo, el resort más exclusivo del Caribe.', 'La Romana es sinónimo de lujo y exclusividad en el Caribe. Casa de Campo, uno de los resorts más prestigiosos del mundo, ofrece campos de golf de campeonato, la marina más grande del Caribe y Altos de Chavón, una réplica de una villa mediterránea del siglo XVI con un anfiteatro espectacular.', 'https://images.unsplash.com/photo-1705507972578-78537a2dda73?w=1200&h=800&fit=crop&q=80', 18.4273, -68.9728, 'Diciembre a Abril', 'Clima tropical seco, ideal durante todo el año.', 'Aeropuerto Internacional La Romana (LRM) o 1.5 horas desde Punta Cana.', '["Casa de Campo Resort","Altos de Chavón","Isla Catalina","Teeth of the Dog Golf"]', '["Langosta al ajillo","Pescado al coco","Chicharrón de cerdo"]', '["playa","lujo","cultura"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('la-vega', 'la-vega', 'La Vega', 'norte', 'Concepción de La Vega', 'draft', 'El corazón del Cibao con el carnaval más famoso del país.', 'La Vega es conocida por tener el carnaval más espectacular de República Dominicana, con sus diablos cojuelos y máscaras elaboradas. También ofrece acceso a Jarabacoa y Constanza, los destinos de montaña más importantes del país.', 'https://images.unsplash.com/photo-1621625287453-3f3ffde85dde?w=1200&h=800&fit=crop&q=80', 19.222, -70.5296, 'Febrero para el carnaval', 'Clima templado en las montañas, más fresco que la costa.', '1.5 horas desde Santo Domingo por autopista.', '["Carnaval de La Vega","Santo Cerro","Acceso a Jarabacoa","Cultura cibaeña"]', '["Chivo liniero","Locrio de pica pica","Habichuelas con dulce"]', '["montaña","cultura","aventura"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories, tagline, intro, slides, themes, traveler_tags, blocks, photo_credits) VALUES ('maria-trinidad-sanchez', 'maria-trinidad-sanchez', 'María Trinidad Sánchez', 'norte', 'Nagua', 'draft', 'Playas espectaculares como Playa Grande y la Laguna Gri-Gri.', 'María Trinidad Sánchez alberga algunas de las playas más espectaculares del norte, incluyendo la famosa Playa Grande, considerada una de las más hermosas del país. La Laguna Gri-Gri en Río San Juan ofrece paseos en bote únicos por manglares y acantilados costeros. Es un destino emergente con enorme potencial turístico.', 'https://images.unsplash.com/photo-1623876355063-15d1d5e5b89b?w=1200&h=800&fit=crop&q=80', 19.3833, -69.95, 'Diciembre a Mayo', 'Clima tropical húmedo con lluvias frecuentes.', '3 horas desde Santo Domingo.', '["Playa Grande","Laguna Gri-Gri","Playa Caletón","Río San Juan"]', '["Pescado con coco","Cangrejo guisado","Casabe"]', '["playa","ecoturismo"]', 'La Costa del Atlántico Indómito', 'Acantilados kársticos, piscinas naturales de agua dulce, cocoteros infinitos y un ambiente auténtico y local: el Atlántico dominicano sin masificar.', '[{"image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dudu%20lagoon%20(2359528937).jpg?width=1600","tag":"Cabrera","title":"Laguna Dudú","subtitle":"Cenotes gemelos de agua dulce","description":"Agua cristalina y fría para nadar, bucear o lanzarse en tirolesa sobre el cenote."},{"image":"https://commons.wikimedia.org/wiki/Special:FilePath/Laguna%20Gri-Gri.jpg?width=1600","tag":"Río San Juan","title":"Laguna Gri Grí","subtitle":"Manglares y piscinas naturales","description":"Botes por el estero hacia La Playita y Playa Caletón. Escenario del Carnavarengue, el único carnaval marino del mundo.","ctaText":"Conocer el Carnavarengue","ctaLink":"#carnavarengue"},{"image":"https://commons.wikimedia.org/wiki/Special:FilePath/Playa%20Grande%20RSJ.jpg?width=1600","tag":"Surf y golf","title":"Playa Grande","subtitle":"Oleaje atlántico","description":"Olas potentes ideales para el surf, rodeadas de un campo de golf de clase mundial."},{"image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nagua%20Dominican%20Republic.jpg?width=1600","tag":"Nagua","title":"Las Gordas","subtitle":"Cuna de la catibía","description":"Empanadas de masa de yuca fresca, crocantes y con rellenos tradicionales, que atraen comensales de todo el país."}]', '[{"id":"carnavarengue","eyebrow":"Río San Juan · desde 1997","title":"Carnavarengue, el único carnaval marino del mundo","text":"Rinde homenaje a la tradición pesquera y a la belleza natural de la zona. Las comparsas desfilan a bordo de botes y lanchas por la Laguna Gri Grí ante el público.","facts":["Los «Carnamares»: disfraces de calamares gigantes, caballitos de mar, peces y langostas","Elaborados por niños, jóvenes y vecinos de los sectores locales","Desfiles, concurso de caretas, música y recorridos ecológicos por la laguna"],"image":"https://commons.wikimedia.org/wiki/Special:FilePath/Laguna%20Gri-Gri.jpg?width=1600"},{"id":"catibia","eyebrow":"Las Gordas, Nagua","title":"La cuna de la empanada de catibía","text":"La catibía, empanada de masa de yuca fresca, tiene raíz taína en todo el país, pero Las Gordas se ganó su fama por la maestría artesanal de su gente: masa perfectamente crocante y rellenos tradicionales que atraen comensales de todas las regiones.","image":""},{"id":"lagunas","eyebrow":"Agua dulce frente al mar","title":"Lagunas, cenotes y manantiales","text":"Una costa kárstica donde el agua dulce brota junto al Atlántico.","facts":["Laguna Dudú (Cabrera): cenotes gemelos y tirolesa","Laguna Gri Grí (Río San Juan): manglares en bote","Laguna de Saladilla (Nagua)"],"image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dudu%20lagoon%20(2359528937).jpg?width=1600"}]', '[{"label":"Aventura y naturaleza","places":["Laguna Dudú","Laguna Gri Grí","Turismo rural en El Factor"]},{"label":"Playas paradisíacas","places":["Playa Grande","Playa Diamante","Playa Caletón"]},{"label":"Cultura y gastronomía","places":["Carnavarengue","Catibías de Las Gordas","Pescado en Matancitas"]}]', '["hero","identidad","temas","municipios","zonas","viajero","ruta-atlantico","acerca","ficha","distancias","itinerario","como-llegar","actividades","destinos","anuncio","parques","hoteles","gastronomia","pasaporte","creditos"]', '["gosheshe (CC BY 2.0)","Pelie777 (CC BY-SA 4.0)","CristoRey99 (CC BY-SA 4.0)"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('monsenor-nouel', 'monsenor-nouel', 'Monseñor Nouel', 'norte', 'Bonao', 'draft', 'Capital Bonao, ciudad de las rondallas y el río Yuna.', 'Monseñor Nouel, con capital en Bonao, es conocida como la Ciudad de las Rondallas por su rica tradición musical navideña. La provincia cuenta con el Río Yuna para deportes acuáticos, montañas para senderismo y una comunidad artística vibrante. Las minas de ferroníquel son parte importante de su economía.', 'https://images.unsplash.com/photo-1762995875707-19c6de2c6fd9?w=1200&h=800&fit=crop&q=80', 18.9417, -70.4083, 'Diciembre para las rondallas, Febrero para carnaval', 'Clima tropical con temperaturas agradables.', '1.5 horas desde Santo Domingo por autopista Duarte.', '["Rondallas de Bonao","Río Yuna","Carnaval de Bonao","Artesanía"]', '["Moro de guandules","Chivo guisado","Habichuelas con dulce"]', '["cultura","aventura"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('monte-cristi', 'monte-cristi', 'Monte Cristi', 'norte', 'San Fernando de Montecristi', 'draft', 'El Morro icónico, cayos vírgenes y salinas en el extremo noroeste.', 'Monte Cristi es una de las provincias más fascinantes y menos exploradas de República Dominicana. Dominada por el icónico perfil de El Morro, ofrece los Cayos Siete Hermanos con playas vírgenes, extensos manglares, salinas históricas y una gastronomía basada en chivo y mariscos. Es el destino perfecto para viajeros aventureros.', 'https://images.unsplash.com/photo-1662622201651-0d6c7dc2c10f?w=1200&h=800&fit=crop&q=80', 19.85, -71.65, 'Noviembre a Mayo', 'Clima seco y cálido, una de las zonas más secas del país.', '4.5 horas desde Santo Domingo.', '["El Morro","Cayos Siete Hermanos","Salinas","Manglares","Punta Rucia"]', '["Chivo liniero","Pescado con coco","Mariscos frescos"]', '["ecoturismo","playa","aventura"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('monte-plata', 'monte-plata', 'Monte Plata', 'este', 'Monte Plata', 'draft', 'Ríos cristalinos, cascadas y ecoturismo a las puertas de Santo Domingo.', 'Monte Plata es el pulmón verde cercano a Santo Domingo, con abundantes ríos cristalinos, cascadas y senderos naturales. Es un destino popular para excursiones de fin de semana con balnearios en los ríos Comate, Guanuma y Ozama. La Cueva Fun-Fun es una de las aventuras subterráneas más emocionantes del Caribe.', 'https://images.unsplash.com/photo-1784495291915-555bc424c453?w=1200&h=800&fit=crop&q=80', 18.8072, -69.785, 'Todo el año', 'Clima tropical húmedo con lluvias frecuentes.', '1 hora desde Santo Domingo.', '["Cueva Fun-Fun","Ríos cristalinos","Balnearios","Senderismo"]', '["Sancocho","Moro de guandules","Habichuelas con dulce"]', '["ecoturismo","aventura","rios"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('pedernales', 'pedernales', 'Pedernales', 'sur', 'Pedernales', 'draft', 'El último paraíso virgen del Caribe con Bahía de las Águilas.', 'Pedernales es la frontera sur con Haití y hogar del tesoro natural más preciado del país: Bahía de las Águilas, una playa virgen de 8 kilómetros considerada una de las más hermosas del mundo. El Parque Nacional Jaragua protege ecosistemas únicos.', 'https://images.unsplash.com/photo-1787186507948-448aead30d99?w=1200&h=800&fit=crop&q=80', 18.0384, -71.744, 'Diciembre a Abril', 'Clima seco y cálido, zona más árida del país.', '5 horas desde Santo Domingo.', '["Bahía de las Águilas","Parque Nacional Jaragua","Laguna de Oviedo","Hoyo de Pelempito"]', '["Chivo guisado","Pescado frito","Casabe"]', '["ecoturismo","playa","aventura"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('peravia', 'peravia', 'Peravia', 'sur', 'Baní', 'draft', 'Capital Baní, tierra del mango banilejo y las dunas costeras.', 'Peravia, con capital en Baní, es famosa por sus mangos considerados los más dulces del mundo, sus espectaculares dunas de arena (las Dunas de Baní), y las salinas de Azua. El pueblo de Las Calderas ofrece playas tranquilas y un ambiente costero relajado.', 'https://images.unsplash.com/photo-1623876355063-15d1d5e5b89b?w=1200&h=800&fit=crop&q=80', 18.2833, -70.3333, 'Junio-Julio para Festival del Mango', 'Clima semiárido en la costa, más húmedo en las montañas.', '1.5 horas desde Santo Domingo.', '["Dunas de Baní","Mango banilejo","Salinas","Playa Las Calderas"]', '["Mango banilejo","Chivo guisado","Dulce de leche","Habichuelas con dulce"]', '["playa","cultura"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories, about, itinerary, airport, transport) VALUES ('puerto-plata', 'puerto-plata', 'Puerto Plata', 'norte', 'San Felipe de Puerto Plata', 'draft', 'La Costa del Ámbar con teleférico, fortaleza histórica y playas doradas.', 'Puerto Plata, conocida como la Costa del Ámbar, combina historia colonial, aventura y belleza natural. El teleférico al Pico Isabel de Torres, la Fortaleza San Felipe y las playas de Sosúa y Cabarete hacen de esta provincia un destino diverso y emocionante.', 'https://images.unsplash.com/photo-1650509570400-90ea78a677b2?w=1200&h=800&fit=crop&q=80', 19.7934, -70.6884, 'Diciembre a Abril', 'Clima tropical con temperaturas de 24-30°C.', 'Aeropuerto Internacional Gregorio Luperón (POP).', '["Teleférico Pico Isabel de Torres","Fortaleza San Felipe","Museo del Ámbar","Kitesurf en Cabarete"]', '["Yaroa","Chivo liniero","Dulce de leche"]', '["playa","cultura","aventura"]', '{"history":"Fundada en 1502 por Nicolás de Ovando con el nombre de San Felipe de Puerto Plata. Fue puerto clave del comercio colonial y sufrió las devastaciones de Osorio en 1605. En el siglo XIX, el general Gregorio Luperón lideró desde aquí la Guerra de Restauración. El turismo masivo llegó en los años 80 con el desarrollo de Playa Dorada.","geography":"Situada en la costa norte (Atlántico), flanqueada por la Cordillera Septentrional. El Pico Isabel de Torres (793 m) domina el paisaje urbano. La provincia cuenta con 120 km de costa con playas de arena dorada y formaciones coralinas.","artAndCulture":"Cuna del ámbar dominicano, con el Museo del Ámbar albergando piezas de hasta 40 millones de años. Las fiestas patronales de San Felipe (mayo) y el carnaval con sus \"taimáscaros\" son tradiciones emblemáticas. La influencia afrocaribeña marca la música y la gastronomía local.","economy":"Turismo (Playa Dorada, Sosúa, Cabarete), zonas francas industriales, producción de ron y tabaco. El puerto de carga de Maimón es importante para el comercio exterior.","demographics":"Aproximadamente 330,000 habitantes. Comunidad cosmopolita con importante presencia de europeos y norteamericanos residentes, especialmente en Sosúa y Cabarete.","pointsOfInterest":[{"name":"Teleférico Pico Isabel de Torres","type":"natural","description":"Único teleférico del Caribe con jardín botánico en la cumbre."},{"name":"Fortaleza San Felipe","type":"histórico","description":"Fortín colonial del s. XVI, hoy museo militar."},{"name":"Museo del Ámbar","type":"cultural","description":"Colección de ámbar dominicano con insectos prehistóricos."},{"name":"Ocean World Adventure Park","type":"entretenimiento","description":"Parque con delfines, leones marinos y acuario."},{"name":"27 Charcos de Damajagua","type":"natural","description":"Cascadas naturales para canyoning y aventura acuática."}],"whatToDo":["Subir en teleférico al Pico Isabel de Torres","Kitesurf y windsurf en Cabarete","Canyoning en los 27 Charcos de Damajagua","Snorkel en los arrecifes de Sosúa","Tour por fábricas de ron y tabaco","Explorar la Fortaleza San Felipe","Visitar el Museo del Ámbar"]}', '[{"dia":1,"titulo":"ALTURA Y NATURALEZA","lugar":"Teleférico & Monte Isabel","desc":"Sube al único teleférico del Caribe y disfruta las vistas panorámicas."},{"dia":2,"titulo":"AVENTURA EXTREMA","lugar":"27 Charcos de Damajagua","desc":"Salta y deslízate por cascadas naturales en la selva."},{"dia":3,"titulo":"PLAYA & CULTURA","lugar":"Sosúa & Museo del Ámbar","desc":"Snorkel en aguas cristalinas y descubre el oro dominicano."}]', '{"nombre":"Aeropuerto Internacional Gregorio Luperón","codigo":"POP","distancia":"15 min"}', '[{"tipo":"avion","desde":"Santo Domingo","duracion":"35 min","descripcion":"Vuelos directos desde SDQ","precio":"$100"},{"tipo":"carro","desde":"Santo Domingo","duracion":"3 horas","descripcion":"Por la autopista Duarte, paisajes montañosos","precio":"$150 (taxi)"},{"tipo":"bus","desde":"Santo Domingo","duracion":"4 horas","descripcion":"Caribe Tours con salidas frecuentes","precio":"$10"}]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories, about, tagline, intro, slides, themes, traveler_tags, blocks, photo_credits, itinerary, airport, transport) VALUES ('samana', 'samana', 'Samaná', 'norte', 'Samaná', 'draft', 'Paraíso ecológico con ballenas jorobadas, cascadas y playas vírgenes.', 'Samaná es un santuario natural que ofrece una experiencia única en el Caribe. Desde el avistamiento de ballenas jorobadas de enero a marzo, hasta las majestuosas cascadas de El Limón y las playas vírgenes de Las Terrenas, este destino cautiva a los amantes de la naturaleza y la aventura.', 'https://images.unsplash.com/photo-1623876355063-15d1d5e5b89b?w=1200&h=800&fit=crop&q=80', 19.2056, -69.3364, 'Enero a Marzo para ballenas, todo el año para playas', 'Clima tropical húmedo, lluvias más frecuentes que en el este.', 'Aeropuerto Internacional El Catey (AZS) o 2.5 horas desde Santo Domingo.', '["Avistamiento de ballenas","Cascada El Limón","Parque Nacional Los Haitises","Playas vírgenes"]', '["Pescado con coco","Cangrejo guisado","Dulce de coco"]', '["playa","ecoturismo","aventura"]', '{"history":"Samaná fue bautizada como \"Bahía de las Flechas\" por Cristóbal Colón en 1493 tras un enfrentamiento con los indígenas ciguayos. En el siglo XIX recibió inmigrantes afroamericanos libertos de EE.UU. que fundaron comunidades como Philadelphia y Bethesda, cuya herencia cultural anglófona persiste hoy.","geography":"Península que se extiende hacia el Atlántico norte, con una topografía montañosa cubierta de bosque tropical húmedo. El Parque Nacional Los Haitises al sur presenta formaciones de mogotes (colinas cónicas) únicas en el Caribe, con cuevas con petroglifos taínos.","artAndCulture":"La cultura samanesa fusiona raíces africanas, taínas y la herencia anglófona de los descendientes de afroamericanos. La música de bambulá y los himnos gospel en inglés conviven con el merengue y la bachata. La Semana Santa en las comunidades de descendientes es una experiencia cultural única.","economy":"Turismo ecológico y de aventura como motor principal. La pesca artesanal, la producción de cacao orgánico y el aceite de coco complementan la economía. El avistamiento de ballenas genera más de $30 millones anuales.","demographics":"Aproximadamente 120,000 habitantes. Comunidad multicultural con presencia de europeos residentes (principalmente franceses e italianos) en Las Terrenas y descendientes afroamericanos en las zonas rurales.","pointsOfInterest":[{"name":"Parque Nacional Los Haitises","type":"natural","description":"Bosque húmedo con mogotes, cuevas taínas y manglares."},{"name":"Cascada El Limón","type":"natural","description":"Caída de agua de entre 40 y 50 metros, accesible a caballo o a pie."},{"name":"Playa Rincón","type":"natural","description":"Votada como una de las 10 mejores playas del mundo."},{"name":"Cayo Levantado","type":"natural","description":"Isla paradisíaca conocida como \"Isla Bacardí\"."},{"name":"Puente de Samaná","type":"histórico","description":"Puente peatonal que cruza la bahía con vistas espectaculares."}],"whatToDo":["Avistamiento de ballenas jorobadas (enero-marzo)","Excursión a la Cascada El Limón","Tour en lancha por Los Haitises","Buceo y snorkel en la costa","Senderismo en la Sierra de Samaná","Paseo a caballo por playas vírgenes","Degustación de cacao orgánico"]}', 'La Península Verde y Marina', 'Hogar de la biodiversidad, la cultura del coco y el avistamiento de ballenas jorobadas: una península donde la selva cae sobre la bahía y una historia afroamericana única en el Caribe sigue viva.', '[{"image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mother%20Humpback%20Whale%20in%20Saman%C3%A1%20Bay%2C%20Dominican%20Republic.jpg?width=1600","tag":"Enero – Marzo","title":"Ballenas jorobadas","subtitle":"Bahía de Samaná","description":"Miles de ballenas llegan cada invierno a aparearse y dar a luz frente a Santa Bárbara de Samaná. Uno de los mejores avistamientos del mundo.","ctaText":"Ver temporada","ctaLink":"#ballenas"},{"image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cayo%20Levantado%2C%20Saman%C3%A1%2032000%2C%20Dominican%20Republic%20-%20panoramio.jpg?width=1600","tag":"Excursión imperdible","title":"Cayo Levantado","subtitle":"La Isla Bacardí","description":"Arena blanca y agua transparente en medio de la bahía, a pocos minutos en bote desde el malecón de Samaná."},{"image":"https://commons.wikimedia.org/wiki/Special:FilePath/DOM%20Santa%20B%C3%A1rbara%20de%20Saman%C3%A1%2C%20El%20Lim%C3%B3n%2C%20Monumento%20Natural%20Salto%20El%20Lim%C3%B3n%200008.jpg?width=1600","tag":"Aventura","title":"Salto El Limón","subtitle":"Entre 40 y 50 metros de cascada","description":"Oculto en la selva, se llega a caballo o a pie por senderos de montaña."},{"image":"https://commons.wikimedia.org/wiki/Special:FilePath/Playa%20Rinc%C3%B3n%20Dec%202020.jpg?width=1600","tag":"Playas paradisíacas","title":"Playa Rincón","subtitle":"Las Galeras","description":"Considerada una de las mejores playas del mundo: kilómetros de arena virgen y cocoteros frente a acantilados."},{"image":"https://commons.wikimedia.org/wiki/Special:FilePath/DOM%20Santa%20B%C3%A1rbara%20de%20Saman%C3%A1%2C%20Los%20Puentes%20de%20Saman%C3%A1%200008.jpg?width=1600","tag":"Santa Bárbara de Samaná","title":"El puente de colores","subtitle":"Hacia Cayo Vigía","description":"Malecón con casas victoriano-caribeñas, Los Haitises y la cocina de coco más auténtica del país."},{"image":"","tag":"La Península Verde","title":"Samaná","subtitle":"Donde la selva abraza el mar","description":"Una península donde la selva cae sobre la bahía y la historia afroamericana sigue viva."}]', '[{"id":"ballenas","eyebrow":"Temporada de enero a marzo","title":"Avistamiento de ballenas jorobadas","text":"Cada invierno, las ballenas jorobadas del Atlántico Norte llegan a la Bahía de Samaná para aparearse y dar a luz. Las excursiones salen desde el malecón de Santa Bárbara de Samaná.","facts":["Salidas desde el malecón de Samaná","Mejor época: mediados de enero a finales de marzo","Se combina con Cayo Levantado en el mismo día"],"image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mother%20Humpback%20Whale%20in%20Saman%C3%A1%20Bay%2C%20Dominican%20Republic.jpg?width=1600"},{"id":"herencia","eyebrow":"Cultura viva","title":"Herencia afroamericana","text":"En el siglo XIX llegaron a Samaná afrodescendientes libres de Estados Unidos. Su legado sigue en las iglesias protestantes como La Churcha, en el inglés samanés que aún se escucha y en tradiciones que no existen en ningún otro lugar del país.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/DOM%20Santa%20B%C3%A1rbara%20de%20Saman%C3%A1%2C%20Malec%C3%B3n%20de%20Saman%C3%A1%200001.jpg?width=1600"},{"id":"haitises","eyebrow":"Parque nacional","title":"Los Haitises","text":"Mogotes cubiertos de selva, manglares y cuevas con arte rupestre taíno, accesibles en bote desde Samaná y Sánchez.","facts":["Cuevas con pictografías y petroglifos taínos","Manglares y aves marinas","Salidas desde Samaná y Sánchez"],"image":"https://commons.wikimedia.org/wiki/Special:FilePath/Los%20Haitises%20Park.jpeg?width=1600"},{"id":"sabores","eyebrow":"Gastronomía","title":"Cocina de coco y mar","text":"El pescado con coco es el plato emblema de la península; en Sánchez reinan los camarones de río y de bahía, y en Las Terrenas la cocina de fusión frente al mar.","image":""}]', '[{"label":"Aventura y naturaleza","places":["Los Haitises","Salto El Limón","Kitesurf en Las Terrenas"]},{"label":"Playas paradisíacas","places":["Playa Rincón","Playa Bonita","Cayo Levantado"]},{"label":"Cultura y gastronomía","places":["Herencia afroamericana","Camarones de Sánchez","Cocina de fusión en Las Terrenas"]}]', '["hero","identidad","temas","municipios","zonas","viajero","ruta-atlantico","acerca","ficha","distancias","itinerario","como-llegar","actividades","destinos","anuncio","parques","hoteles","gastronomia","pasaporte","creditos"]', '["Caballero1967 (CC BY-SA 4.0)","Panoramio (CC BY 3.0)","-wuppertaler (CC BY 4.0)","Danu Widjajanto (CC BY-SA 4.0)","Anton Bielousov (CC BY-SA 3.0)"]', '[{"dia":1,"titulo":"AVENTURA MARINA","lugar":"Santuario de Ballenas & Cayo Levantado","desc":"Salida en bote para un encuentro mágico con las ballenas jorobadas y atardecer en Cayo Levantado."},{"dia":2,"titulo":"SELVA ADENTRO","lugar":"Senderismo al Salto del Limón","desc":"Caminata por el bosque lluvioso hasta la impresionante cascada de 40 metros."},{"dia":3,"titulo":"PLAYAS VÍRGENES","lugar":"Playa Rincón","desc":"Relájate en una de las 10 mejores playas del mundo."}]', '{"nombre":"Aeropuerto Internacional El Catey","codigo":"AZS","distancia":"45 min"}', '[{"tipo":"avion","desde":"Santo Domingo","duracion":"35 min","descripcion":"Vuelos directos diarios desde SDQ","precio":"$120"},{"tipo":"carro","desde":"Santo Domingo","duracion":"2.5 horas","descripcion":"Por la autopista del Nordeste, ruta escénica","precio":"$80 (taxi)"},{"tipo":"bus","desde":"Santo Domingo","duracion":"3 horas","descripcion":"Transporte Caribe Tours con salidas frecuentes","precio":"$8"},{"tipo":"barco","desde":"Sabana de la Mar","duracion":"1 hora","descripcion":"Ferry panorámico con vista a la bahía","precio":"$5"}]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('san-cristobal', 'san-cristobal', 'San Cristóbal', 'sur', 'San Cristóbal', 'draft', 'Cuna de la Constitución dominicana con cuevas, ríos y el Castillo del Cerro.', 'San Cristóbal es conocida como la Cuna de la Constitución, ya que aquí se firmó la primera Constitución de la República Dominicana en 1844. La provincia ofrece el Castillo del Cerro de la era de Trujillo, las cuevas de El Pomier con arte rupestre taíno, ríos para balnearios y un rico patrimonio histórico-cultural.', 'https://images.unsplash.com/photo-1777380535163-182463e53e0b?w=1200&h=800&fit=crop&q=80', 18.417, -70.105, 'Todo el año', 'Clima tropical con temperaturas moderadas en las montañas.', '30 minutos desde Santo Domingo.', '["Cuna de la Constitución","Castillo del Cerro","Cuevas de El Pomier","Ríos y balnearios"]', '["Pastelón","Moro de guandules","Dulces criollos"]', '["cultura","ecoturismo"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('san-jose-de-ocoa', 'san-jose-de-ocoa', 'San José de Ocoa', 'sur', 'San José de Ocoa', 'draft', 'La Suiza del Caribe con montañas verdes y café de altura.', 'San José de Ocoa es conocida como la Suiza del Caribe por sus montañas verdes y clima fresco. Es un destino emergente de ecoturismo con senderos de montaña, cascadas escondidas y fincas de café orgánico de altura. La provincia ofrece una escapada refrescante del calor costero.', 'https://images.unsplash.com/photo-1773394702623-0d0024246042?w=1200&h=800&fit=crop&q=80', 18.5431, -70.5061, 'Todo el año, especialmente dic-mar', 'Clima fresco de montaña, 18-25°C.', '2 horas desde Santo Domingo.', '["Montañas verdes","Café de altura","Cascadas","Senderismo"]', '["Café orgánico","Chivo guisado","Habichuelas con dulce"]', '["montaña","ecoturismo"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('san-juan', 'san-juan', 'San Juan', 'sur', 'San Juan de la Maguana', 'draft', 'El Valle de San Juan, puerta sur al Pico Duarte y tradición agrícola.', 'San Juan de la Maguana es una de las provincias más grandes del país, con el fértil Valle de San Juan. Es la puerta sur para expediciones al Pico Duarte y ofrece el misterioso Corral de los Indios, un sitio ceremonial taíno. La provincia tiene una rica tradición ganadera y agrícola con su famoso arroz.', 'https://images.unsplash.com/photo-1758298134996-520fae77469a?w=1200&h=800&fit=crop&q=80', 18.8056, -71.2296, 'Noviembre a Abril', 'Clima variado, cálido en el valle y fresco en las montañas.', '3 horas desde Santo Domingo.', '["Corral de los Indios","Ruta sur al Pico Duarte","Valle fértil","Presa de Sabaneta"]', '["Chenchén con chivo","Habichuelas con dulce","Longaniza"]', '["montaña","cultura","aventura"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('san-pedro-de-macoris', 'san-pedro-de-macoris', 'San Pedro de Macorís', 'este', 'San Pedro de Macorís', 'draft', 'La Cuna de los Shortstops y tierra de los Guloya, Patrimonio Inmaterial UNESCO.', 'San Pedro de Macorís es famosa por producir más jugadores de Grandes Ligas de béisbol per cápita que cualquier ciudad del mundo. Es también hogar de los Guloyas, una tradición de danza y teatro callejero declarada Patrimonio Inmaterial de la Humanidad por la UNESCO. Sus malecones y playas complementan su rica oferta cultural.', 'https://images.unsplash.com/photo-1762995875707-19c6de2c6fd9?w=1200&h=800&fit=crop&q=80', 18.4537, -69.3088, 'Todo el año', 'Clima tropical con brisas marinas.', '1 hora desde Santo Domingo.', '["Cuna de los Shortstops","Guloyas UNESCO","Malecón","Estadio Tetelo Vargas"]', '["Domplines","Guavaberry","Yaniqueques","Pescado frito"]', '["cultura","playa"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('sanchez-ramirez', 'sanchez-ramirez', 'Sánchez Ramírez', 'norte', 'Cotuí', 'draft', 'Presa de Hatillo, la más grande del país, rodeada de naturaleza.', 'Sánchez Ramírez, con capital en Cotuí, es hogar de la Presa de Hatillo, la más grande del Caribe, que crea un impresionante lago artificial rodeado de montañas verdes. La provincia ofrece turismo rural, pesca deportiva, senderos ecológicos y una rica tradición agrícola basada en el arroz y el cacao.', 'https://images.unsplash.com/photo-1681738623292-3a755d6c8611?w=1200&h=800&fit=crop&q=80', 19.055, -70.1533, 'Noviembre a Abril', 'Clima tropical con temperaturas moderadas.', '2 horas desde Santo Domingo.', '["Presa de Hatillo","Lago artificial","Turismo rural","Pesca deportiva"]', '["Arroz con pollo","Moro de habichuelas","Dulce de coco"]', '["ecoturismo","aventura"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories, about) VALUES ('santiago', 'santiago', 'Santiago', 'norte', 'Santiago de los Caballeros', 'draft', 'La Ciudad Corazón, capital cultural y económica del Cibao.', 'Santiago de los Caballeros es la segunda ciudad más importante de República Dominicana. Conocida como la Ciudad Corazón, es el centro cultural y económico de la región del Cibao, famosa por su producción de tabaco, ron y su vibrante escena artística y gastronómica.', 'https://images.unsplash.com/photo-1773654757960-360272fa8205?w=1200&h=800&fit=crop&q=80', 19.4517, -70.697, 'Todo el año', 'Clima tropical con temperaturas de 22-30°C.', 'Aeropuerto Internacional del Cibao (STI).', '["Monumento a los Héroes","Centro León","Fábricas de cigarros","Gastronomía cibaeña"]', '["Yaroa","Chivo liniero","Morir soñando"]', '["cultura","ciudad","montaña"]', '{"history":"Fundada en 1495 por 30 caballeros de la Orden de Santiago, es la segunda ciudad más antigua fundada por europeos en el Nuevo Mundo. Jugó un papel crucial en las luchas independentistas y la Restauración de la República en 1863. El Monumento a los Héroes de la Restauración, inaugurado en 1944, es su ícono más representativo.","geography":"Situada en el Valle del Cibao, la región agrícola más fértil del país, a 178 metros sobre el nivel del mar. Rodeada por la Cordillera Central al sur y la Cordillera Septentrional al norte.","artAndCulture":"Capital cultural del Cibao, hogar del Centro León (uno de los museos más importantes del Caribe), galerías de arte y una vibrante escena de música urbana. Las fábricas artesanales de cigarros premium y la cultura del tabaco son parte integral de su identidad.","economy":"Segunda economía del país. Líder en manufactura de tabaco (cigarros premium), zonas francas, agroindustria y comercio. La provincia aporta el 10% del PIB nacional.","demographics":"Más de 1 millón de habitantes en el área metropolitana. Segunda ciudad más poblada del país, con una clase media en crecimiento y universidades de prestigio como PUCMM y UTESA.","pointsOfInterest":[{"name":"Monumento a los Héroes","type":"histórico","description":"Torre de 67 metros con vista panorámica de la ciudad y el valle."},{"name":"Centro León","type":"cultural","description":"Museo de arte, historia y cultura dominicana de clase mundial."},{"name":"Calle del Sol","type":"cultural","description":"Arteria comercial principal con arquitectura victoriana y art déco."},{"name":"Fortaleza San Luis","type":"histórico","description":"Fortín colonial restaurado con exposiciones históricas."}],"whatToDo":["Visitar el Centro León y sus exposiciones","Tour por fábricas de cigarros artesanales","Subir al Monumento a los Héroes al atardecer","Degustar gastronomía cibaeña auténtica","Explorar la vida nocturna del centro","Recorrer la Calle del Sol y sus tiendas"]}');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('santiago-rodriguez', 'santiago-rodriguez', 'Santiago Rodríguez', 'norte', 'San Ignacio de Sabaneta', 'draft', 'Cuna de la Restauración dominicana con la Presa de Tavera.', 'Santiago Rodríguez, con capital en Sabaneta, es la Cuna de la Restauración, donde en 1863 se inició la guerra que restauró la república tras la anexión a España. La provincia ofrece la impresionante Presa de Tavera-Bao, montañas de la Cordillera Central y un patrimonio histórico ligado a la identidad nacional.', 'https://images.unsplash.com/photo-1602298674761-700e96568f5f?w=1200&h=800&fit=crop&q=80', 19.4683, -71.3361, 'Agosto para fiestas de la Restauración', 'Clima tropical fresco en las montañas.', '4 horas desde Santo Domingo.', '["Cuna de la Restauración","Presa de Tavera","Montañas","Historia patriótica"]', '["Chivo liniero","Habichuelas con dulce","Arroz con pollo"]', '["ecoturismo","cultura"]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories, about, itinerary, airport, transport) VALUES ('santo-domingo', 'santo-domingo', 'Santo Domingo', 'santo-domingo', 'Santo Domingo Este', 'draft', 'La primera ciudad del Nuevo Mundo, patrimonio de la humanidad.', 'Santo Domingo, fundada en 1496, es la ciudad más antigua del Nuevo Mundo. La Zona Colonial, declarada Patrimonio de la Humanidad por la UNESCO, alberga tesoros históricos como la primera catedral, el primer hospital y la primera universidad de las Américas. Una metrópolis vibrante que combina historia, gastronomía y vida nocturna.', 'https://images.unsplash.com/photo-1650171111438-ea9bc8c675fe?w=1200&h=800&fit=crop&q=80', 18.4861, -69.9312, 'Todo el año', 'Clima tropical con temperaturas de 25-32°C.', 'Aeropuerto Internacional Las Américas (SDQ).', '["Zona Colonial UNESCO","Alcázar de Colón","Malecón","Gastronomía de clase mundial"]', '["La Bandera","Sancocho","Mangú","Chimichurri"]', '["cultura","ciudad"]', '{"history":"Fundada el 5 de agosto de 1496 por Bartolomé Colón, Santo Domingo es la primera ciudad permanente del Nuevo Mundo. Fue capital del imperio español en las Américas durante más de un siglo. La Zona Colonial alberga las primeras instituciones europeas del continente: la primera catedral (1521), el primer hospital (1503), la primera universidad (1538) y el primer monasterio.","geography":"Situada en la costa sur de la isla, en la desembocadura del río Ozama. La ciudad se extiende sobre una llanura costera con elevaciones menores. El malecón recorre 12 km a lo largo del mar Caribe.","artAndCulture":"Santo Domingo es el epicentro cultural del país con más de 20 museos, teatros como el Teatro Nacional Eduardo Brito y el Palacio de Bellas Artes. La escena artística contemporánea florece en galerías de la Zona Colonial y el barrio de Gazcue. El merengue, declarado Patrimonio Inmaterial de la Humanidad por la UNESCO, tiene aquí su mayor expresión.","politicalDivision":"El Distrito Nacional (DN) alberga la capital. La provincia de Santo Domingo se divide en 4 municipios: Santo Domingo Este, Santo Domingo Oeste, Santo Domingo Norte y Boca Chica, más 7 distritos municipales.","economy":"Como capital, concentra el 35% del PIB nacional. Los sectores dominantes son servicios financieros, comercio, telecomunicaciones, turismo urbano y zonas francas industriales. Es sede de las principales instituciones gubernamentales y corporativas.","demographics":"La Gran Santo Domingo supera los 4 millones de habitantes, representando cerca del 40% de la población nacional. Es una ciudad multicultural con comunidades de más de 100 nacionalidades.","location":"Costa sur de la isla, a orillas del mar Caribe y el río Ozama. A 150 km de Punta Cana, 155 km de Santiago y 245 km de Samaná.","pointsOfInterest":[{"name":"Zona Colonial","type":"histórico","description":"Patrimonio de la Humanidad UNESCO con más de 300 edificaciones coloniales."},{"name":"Alcázar de Colón","type":"histórico","description":"Palacio de Diego Colón, hoy museo virreinal con vistas al río Ozama."},{"name":"Los Tres Ojos","type":"natural","description":"Sistema de cuevas con lagos subterráneos de aguas cristalinas."},{"name":"Jardín Botánico Nacional","type":"natural","description":"Uno de los jardines botánicos más grandes del Caribe."},{"name":"Centro León Cultural","type":"cultural","description":"Espacio de arte, historia y cultura dominicana."},{"name":"Faro a Colón","type":"histórico","description":"Monumento en forma de cruz que alberga los restos de Cristóbal Colón."}],"whatToDo":["Recorrido a pie por la Zona Colonial","Tour gastronómico por los mercados y restaurantes","Visitar museos y galerías de arte","Disfrutar del malecón al atardecer","Explorar las cuevas de Los Tres Ojos","Vida nocturna en la Zona Colonial y Piantini","Compras en Blue Mall y Ágora Mall","Paseo en bote por el río Ozama"]}', '[{"dia":1,"titulo":"HISTORIA VIVA","lugar":"Zona Colonial","desc":"Recorre las calles más antiguas de América y visita la Catedral Primada."},{"dia":2,"titulo":"SABORES LOCALES","lugar":"Tour Gastronómico","desc":"Prueba la mejor comida dominicana en mercados y restaurantes locales."},{"dia":3,"titulo":"CULTURA & BAILE","lugar":"Clase de Merengue & Vida Nocturna","desc":"Aprende a bailar merengue y disfruta de la noche capitalina."}]', '{"nombre":"Aeropuerto Internacional Las Américas","codigo":"SDQ","distancia":"30 min"}', '[{"tipo":"avion","desde":"Miami","duracion":"2.5 horas","descripcion":"Vuelos directos desde principales ciudades de USA y Europa"},{"tipo":"carro","desde":"Punta Cana","duracion":"2 horas","descripcion":"Por la autopista del Este"},{"tipo":"bus","desde":"Puerto Plata","duracion":"4 horas","descripcion":"Caribe Tours y Metro","precio":"$12"}]');
INSERT OR IGNORE INTO provinces (id, slug, name, region, capital, status, short_description, description, image_url, latitude, longitude, best_time, weather_info, how_to_get_there, highlights, typical_dishes, categories) VALUES ('valverde', 'valverde', 'Valverde', 'norte', 'Mao', 'draft', 'Capital Mao, tierra del arroz dominicano y la presa de Monción.', 'Valverde, con capital en Mao, es el principal productor de arroz de República Dominicana, el alimento fundamental de la dieta dominicana. La Presa de Monción y sus alrededores ofrecen paisajes naturales para excursiones. La provincia mantiene tradiciones agrícolas arraigadas y un estilo de vida rural auténtico.', 'https://images.unsplash.com/photo-1777380535163-182463e53e0b?w=1200&h=800&fit=crop&q=80', 19.5872, -71.0828, 'Noviembre a Abril', 'Clima cálido y seco en el valle.', '3.5 horas desde Santo Domingo.', '["Capital del arroz","Presa de Monción","Agricultura tradicional","Gastronomía rural"]', '["Arroz dominicano","Habichuelas guisadas","Chivo liniero"]', '["cultura"]');
