INSERT OR IGNORE INTO municipalities (id, province_id, slug, name, is_capital, short_description, highlights) VALUES ('nagua', (SELECT id FROM provinces WHERE slug = 'maria-trinidad-sanchez'), 'nagua', 'Nagua', 1, 'Ciudad costera y laboriosa, famosa por su producción de coco, su gente hospitalaria y su animado carnaval.', '["Pescado fresco frente al mar en Matancitas","Laguna de Saladilla","Playas de arena dorada menos masificadas","Las Gordas, cuna de las empanadas de catibía"]');
INSERT OR IGNORE INTO municipalities (id, province_id, slug, name, is_capital, short_description, highlights) VALUES ('cabrera', (SELECT id FROM provinces WHERE slug = 'maria-trinidad-sanchez'), 'cabrera', 'Cabrera', 0, 'Acantilados imponentes que caen sobre el Atlántico y manantiales de agua cristalina y fría que brotan cerca de la costa.', '["Laguna Dudú y sus cenotes gemelos con tirolesa","Playa Diamante: aguas tranquilas y poco profundas, ideal para familias","Playa Caletón"]');
INSERT OR IGNORE INTO municipalities (id, province_id, slug, name, is_capital, short_description, highlights) VALUES ('el-factor', (SELECT id FROM provinces WHERE slug = 'maria-trinidad-sanchez'), 'el-factor', 'El Factor', 0, 'El corazón agrícola, ganadero y de conexión vial de la provincia: el valle fértil que une la cordillera con la costa atlántica.', '["Turismo rural","Quesos y dulces artesanales"]');
INSERT OR IGNORE INTO municipalities (id, province_id, slug, name, is_capital, short_description, highlights) VALUES ('rio-san-juan', (SELECT id FROM provinces WHERE slug = 'maria-trinidad-sanchez'), 'rio-san-juan', 'Río San Juan', 0, 'Pueblo de pescadores pintoresco, alegre y colorido, con canales de manglares junto a una de las lagunas ecoturísticas más bellas del país.', '["Laguna Gri Grí en bote hacia La Playita y Playa Caletón","Playa Grande: surf y golf de clase mundial","Carnavarengue, el único carnaval marino del mundo"]');
