INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('bavaro', (SELECT id FROM provinces WHERE slug = 'la-altagracia'), 'salvaleon-de-higuey', 'bavaro', 'Bávaro', 1, 'La playa más fotografiada del Caribe con arenas blancas perfectas.', 'Bávaro alberga una de las playas más hermosas del mundo, reconocida por la UNESCO. Sus aguas cristalinas color turquesa y su arena blanca como el azúcar la convierten en el escenario perfecto para unas vacaciones de ensueño.', '["Playa Bávaro","Resorts de lujo","Vida nocturna","Compras"]', 'https://images.unsplash.com/photo-1628281158250-48001a7687d3?w=1200&h=800&fit=crop&q=80', 18.687, -68.4514);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('punta-cana', (SELECT id FROM provinces WHERE slug = 'la-altagracia'), 'salvaleon-de-higuey', 'punta-cana', 'Punta Cana', 1, 'El destino turístico más famoso del Caribe con playas de ensueño.', 'Punta Cana es el corazón turístico del Caribe, famoso por sus 48 kilómetros de playas de arena blanca bordeadas de cocoteros. Aquí encontrarás los mejores resorts todo incluido, campos de golf de campeonato, y una infinidad de actividades acuáticas y de aventura.', '["Playa Bávaro","Hoyo Azul","Indigenous Eyes Ecological Park","Golf de clase mundial","Vida nocturna vibrante"]', 'https://images.unsplash.com/photo-1672841828478-2fad29c8fa25?w=1200&h=800&fit=crop&q=80', 18.5601, -68.3725);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('cap-cana', (SELECT id FROM provinces WHERE slug = 'la-altagracia'), 'salvaleon-de-higuey', 'cap-cana', 'Cap Cana', 1, 'El destino más exclusivo del Caribe con marina y golf de clase mundial.', 'Cap Cana es el epítome del lujo caribeño. Este desarrollo exclusivo cuenta con la marina más grande del Caribe, el campo de golf Punta Espada diseñado por Jack Nicklaus, y Juanillo Beach, una de las playas más exclusivas de la región.', '["Marina Cap Cana","Punta Espada Golf","Juanillo Beach","Scape Park"]', 'https://images.unsplash.com/photo-1619680939776-4eadd78709a4?w=1200&h=800&fit=crop&q=80', 18.4501, -68.4094);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('uvero-alto', (SELECT id FROM provinces WHERE slug = 'la-altagracia'), 'salvaleon-de-higuey', 'uvero-alto', 'Uvero Alto', 1, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('bayahibe', (SELECT id FROM provinces WHERE slug = 'la-altagracia'), 'san-rafael-del-yuma', 'bayahibe', 'Bayahíbe', 1, 'Pueblo de pescadores con acceso a las mejores islas del Caribe.', 'Bayahíbe es un encantador pueblo de pescadores que sirve como puerta de entrada a la Isla Saona, la Isla Catalina y el Parque Nacional del Este. Sus aguas cristalinas son perfectas para buceo y snorkeling, con algunos de los arrecifes más saludables del Caribe.', '["Isla Saona","Isla Catalina","Buceo en arrecifes","Parque Nacional del Este"]', 'https://images.unsplash.com/photo-1635450695849-bde4bea19b5f?w=1200&h=800&fit=crop&q=80', 18.369, -68.837);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('boca-de-yuma', (SELECT id FROM provinces WHERE slug = 'la-altagracia'), 'san-rafael-del-yuma', 'boca-de-yuma', 'Boca de Yuma', 1, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('las-terrenas', (SELECT id FROM provinces WHERE slug = 'samana'), 'las-terrenas', 'las-terrenas', 'Las Terrenas', 1, 'Villa bohemia con playas paradisíacas y ambiente cosmopolita.', 'Las Terrenas es un encantador pueblo costero con un toque europeo, particularmente francés e italiano. Sus playas vírgenes, restaurantes gourmet y ambiente relajado lo convierten en el destino favorito de viajeros que buscan autenticidad y belleza natural.', '["Playa Cosón","Playa Bonita","Cascada El Limón","Gastronomía internacional","Avistamiento de ballenas"]', 'https://images.unsplash.com/photo-1635450695849-bde4bea19b5f?w=1200&h=800&fit=crop&q=80', 19.312, -69.542);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('las-galeras', (SELECT id FROM provinces WHERE slug = 'samana'), 'samana', 'las-galeras', 'Las Galeras', 1, 'El rincón más virgen de Samaná con Playa Rincón.', 'Las Galeras es un pequeño pueblo de pescadores en el extremo este de la península de Samaná. Aquí encontrarás Playa Rincón, considerada una de las 10 mejores playas del mundo, accesible solo por bote o camino de tierra.', '["Playa Rincón","Playa Frontón","Buceo","Pesca artesanal"]', 'https://images.unsplash.com/photo-1623876355063-15d1d5e5b89b?w=1200&h=800&fit=crop&q=80', 19.2689, -69.2458);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('cayo-levantado', (SELECT id FROM provinces WHERE slug = 'samana'), 'samana', 'cayo-levantado', 'Cayo Levantado', 1, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('cabarete', (SELECT id FROM provinces WHERE slug = 'puerto-plata'), 'sosua', 'cabarete', 'Cabarete', 1, 'Capital mundial del kitesurf y windsurf con vibra surfista.', 'Cabarete es reconocido internacionalmente como uno de los mejores destinos del mundo para deportes acuáticos de viento. Su bahía ofrece condiciones perfectas para kitesurf y windsurf, mientras que su ambiente relajado atrae a una comunidad internacional de deportistas y amantes del mar.', '["Kitesurf","Windsurf","Playa Cabarete","Vida nocturna"]', 'https://images.unsplash.com/photo-1650509570400-90ea78a677b2?w=1200&h=800&fit=crop&q=80', 19.758, -70.4163);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('sosua', (SELECT id FROM provinces WHERE slug = 'puerto-plata'), 'sosua', 'sosua', 'Sosúa', 1, 'Playa de aguas cristalinas con herencia judía y ambiente vibrante.', 'Sosúa es famosa por su hermosa playa en forma de herradura con aguas cristalinas perfectas para snorkeling. El pueblo tiene una fascinante historia como refugio de judíos europeos durante la Segunda Guerra Mundial, visible en su museo y arquitectura.', '["Playa Sosúa","Museo Judío","Snorkeling","Tiendas de artesanías"]', 'https://images.unsplash.com/photo-1672841828478-2fad29c8fa25?w=1200&h=800&fit=crop&q=80', 19.7549, -70.5196);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('playa-dorada', (SELECT id FROM provinces WHERE slug = 'puerto-plata'), 'san-felipe-de-puerto-plata', 'playa-dorada', 'Playa Dorada', 1, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('jarabacoa', (SELECT id FROM provinces WHERE slug = 'la-vega'), 'jarabacoa', 'jarabacoa', 'Jarabacoa', 1, 'La ciudad de la eterna primavera con aventura y naturaleza.', 'Jarabacoa es el destino de montaña más importante de República Dominicana, conocido como la ciudad de la eterna primavera por su clima fresco. Rodeado de ríos, cascadas y pinos, ofrece actividades de aventura como rafting, canyoning, parapente y senderismo hacia el Pico Duarte.', '["Salto de Jimenoa","Rafting en Río Yaque","Pico Duarte","Parapente","Café de altura"]', 'https://images.unsplash.com/photo-1784495535609-fa9e4f4c700a?w=1200&h=800&fit=crop&q=80', 19.12, -70.64);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('constanza', (SELECT id FROM provinces WHERE slug = 'la-vega'), 'constanza', 'constanza', 'Constanza', 1, 'El valle más alto del Caribe con clima de montaña y fresas.', 'Constanza, ubicada a 1,200 metros de altura, es el valle más alto del Caribe. Su clima único permite el cultivo de fresas, flores y vegetales. Es la puerta de entrada a las montañas más altas de las Antillas y ofrece paisajes espectaculares.', '["Valle de Constanza","Cultivo de fresas","Salto de Aguas Blancas","Reserva Valle Nuevo"]', 'https://images.unsplash.com/photo-1732125558160-fa97f8404c0b?w=1200&h=800&fit=crop&q=80', 18.91, -70.75);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('ciudad-colonial', (SELECT id FROM provinces WHERE slug = 'distrito-nacional'), 'santo-domingo-de-guzman', 'ciudad-colonial', 'Ciudad Colonial', 1, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('malecon-sd', (SELECT id FROM provinces WHERE slug = 'distrito-nacional'), 'santo-domingo-de-guzman', 'malecon-sd', 'Malecón de Santo Domingo', 1, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('boca-chica', (SELECT id FROM provinces WHERE slug = 'santo-domingo'), 'boca-chica', 'boca-chica', 'Boca Chica', 1, 'La playa más cercana a Santo Domingo con aguas tranquilas.', 'Boca Chica es la playa más cercana a la capital, conocida por sus aguas poco profundas y tranquilas protegidas por un arrecife natural. Es el destino de fin de semana favorito de los capitalinos y ofrece una animada escena de restaurantes y bares frente al mar.', '["Aguas tranquilas","Restaurantes de mariscos","Ambiente festivo","Cerca del aeropuerto"]', 'https://images.unsplash.com/photo-1623876355063-15d1d5e5b89b?w=1200&h=800&fit=crop&q=80', 18.4461, -69.6053);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('juan-dolio', (SELECT id FROM provinces WHERE slug = 'san-pedro-de-macoris'), 'guayacanes', 'juan-dolio', 'Juan Dolio', 1, 'Destino de playa tranquilo entre Santo Domingo y Punta Cana.', 'Juan Dolio es un destino de playa más tranquilo y relajado, situado entre la capital y los grandes resorts del este. Sus playas de arena blanca y palmeras ofrecen un escape perfecto sin las multitudes, con buenos restaurantes y hoteles boutique.', '["Playas tranquilas","Golf","Ambiente relajado","Vida nocturna moderada"]', 'https://images.unsplash.com/photo-1623876355063-15d1d5e5b89b?w=1200&h=800&fit=crop&q=80', 18.4281, -69.4267);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('bahia-de-las-aguilas', (SELECT id FROM provinces WHERE slug = 'pedernales'), 'pedernales', 'bahia-de-las-aguilas', 'Bahía de las Águilas', 1, 'La playa más hermosa y virgen de todo el Caribe.', 'Bahía de las Águilas es considerada la playa más hermosa del Caribe y una de las mejores del mundo. Con 8 kilómetros de arena blanca inmaculada y aguas cristalinas, es un paraíso virgen protegido dentro del Parque Nacional Jaragua, sin desarrollo turístico masivo.', '["8 km de playa virgen","Aguas cristalinas","Sin desarrollo","Parque Nacional Jaragua"]', 'https://images.unsplash.com/photo-1595781932977-2616086a6fb9?w=1200&h=800&fit=crop&q=80', 17.8167, -71.6333);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('cabo-rojo', (SELECT id FROM provinces WHERE slug = 'pedernales'), 'pedernales', 'cabo-rojo', 'Cabo Rojo', 1, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO destinations (id, province_id, municipality_id, slug, name, is_popular, short_description, description, highlights, image_url, latitude, longitude) VALUES ('bahia-de-neiba', (SELECT id FROM provinces WHERE slug = 'barahona'), 'santa-cruz-de-barahona', 'bahia-de-neiba', 'Bahía de Neiba / Costera', 1, NULL, NULL, NULL, NULL, NULL, NULL);
